// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {C} from "../src/C_under_test.sol";

contract InvMutTest is Test {
    C c;
    function setUp() public { c = new C(); }
    function testFuzz_property(uint timeInput) public {
        // Ensure we can set a future timestamp that is greater than the current pastBlockTime
        uint currentPastBlockTime = c.pastBlockTime();
        uint futureTime = bound(timeInput, currentPastBlockTime + 1, block.timestamp + 1000000);
        vm.warp(futureTime);

        // Try calling fallback with exactly 10 ether
        (bool success, ) = address(c).call{value: 10 ether}("");

        // If the call succeeded, pastBlockTime must have been updated to futureTime
        if (success) {
            assertTrue(c.pastBlockTime() == futureTime, "pastBlockTime not updated after successful fallback call");
        }
    }
}

